	this.frame_0 = function() {
		this.stop();
		var root = this;
		
		// ================= DATA 10 SOAL =================
		window.masterSoal = [
		    {frm:1,  k:"D"},
		    {frm:2,  k:"C"},
		    {frm:3,  k:"A"},
		    {frm:4,  k:"A"},
		    {frm:5,  k:"B"},
		    {frm:6,  k:"C"},
		    {frm:7,  k:"B"},
		    {frm:8,  k:"D"},
		    {frm:9,  k:"C"},
		    {frm:10, k:"A"}
		];
		
		window.soalAcak = [];
		window.indeks = 0;
		window.skorBenar = 0;
		window.jawabanUser = "";
		
		// ================= FUNGSI ACAK =================
		function shuffle(array){
		    for (var i = array.length - 1; i > 0; i--) {
		        var j = Math.floor(Math.random() * (i + 1));
		        
		        var temp = array[i];
		        array[i] = array[j];
		        array[j] = temp;
		    }
		    return array;
		}
		
		// ================= BUTTON MULAI =================
		root.btn_mulai.cursor = "pointer";
		root.btn_mulai.mouseEnabled = true;
		root.btn_mulai.removeAllEventListeners();
		
		root.btn_mulai.on("click", function(){
		
		    // Reset nilai
		    window.indeks = 0;
		    window.skorBenar = 0;
		    window.jawabanUser = "";
		
		    // Acak soal
		    window.soalAcak = shuffle(window.masterSoal.slice());
		
		    // Pindah ke soal pertama
		    root.gotoAndStop(window.soalAcak[window.indeks].frm);
		});
		
		
		this.btn_back_evaluasi.cursor = "pointer";
		this.btn_back_evaluasi.on("click", function() {
		    exportRoot.gotoAndStop("menu_utama");
		}.bind(this));
	}
	this.frame_1 = function() {
		this.stop();
		var root = this;
		
		// ================= GUARD =================
		if (!window.soalAcak || window.soalAcak.length === 0){
		    root.gotoAndStop(0);
		}
		
		// ================= NOMOR SOAL =================
		if(root.no_soal){
		    root.no_soal.text = String(window.indeks + 1);
		}
		
		// ================= RESET AWAL SOAL =================
		window.jawabanUser = ""; // Kosongkan jawaban di awal soal
		root.btn_next.visible = false; // Sembunyikan tombol next
		
		// Pastikan semua tombol muncul dan terang kembali
		let pilihan = [root.btn_a, root.btn_b, root.btn_c, root.btn_d];
		for(let i=0; i<pilihan.length; i++){
		    pilihan[i].visible = true;
		    pilihan[i].alpha = 1; 
		    pilihan[i].cursor = "pointer";
		    pilihan[i].mouseEnabled = true;
		    pilihan[i].removeAllEventListeners();
		}
		root.btn_next.removeAllEventListeners();
		root.btn_next.cursor = "pointer";
		
		// ================= FUNGSI PILIH (BISA GANTI-GANTI) =================
		function pilih(p){
		    window.jawabanUser = p; // Update variabel jawaban setiap kali klik
		
		    // Reset semua tombol jadi redup dulu
		    root.btn_a.alpha = 0.3;
		    root.btn_b.alpha = 0.3;
		    root.btn_c.alpha = 0.3;
		    root.btn_d.alpha = 0.3;
		
		    // Terangkan hanya tombol yang dipilih sekarang
		    root["btn_" + p.toLowerCase()].alpha = 1;
		
		    // Tampilkan tombol next setelah user memilih sesuatu
		    root.btn_next.visible = true;
		    console.log("Jawaban saat ini: " + window.jawabanUser);
		}
		
		// ================= EVENT JAWABAN =================
		root.btn_a.on("click", function(){ pilih("A"); });
		root.btn_b.on("click", function(){ pilih("B"); });
		root.btn_c.on("click", function(){ pilih("C"); });
		root.btn_d.on("click", function(){ pilih("D"); });
		
		// ================= TOMBOL NEXT (KUNCI JAWABAN DI SINI) =================
		root.btn_next.on("click", function(){
		
		    // 1. Cek jawaban terakhir yang dipilih user sebelum pindah
		    if(window.jawabanUser === "") return;
		
		    // 2. Kunci skor (hitung apakah benar/salah)
		    if(window.jawabanUser === window.soalAcak[window.indeks].k){
		        window.skorBenar++;
		    }
		
		    // 3. Pindah soal atau ke hasil
		    window.indeks++;
		
		    if(window.indeks < window.soalAcak.length){
		        root.gotoAndStop(window.soalAcak[window.indeks].frm);
		    }else{
		        root.gotoAndStop(11); // FRAME HASIL (Emoji Menangis/Bahagia)
		    }
		});
	}
