if (loop == null) { loop = true; }
if (reversed == null) { reversed = false; }
	var props = new Object();
	props.mode = mode;
	props.startPosition = startPosition;
	props.labels = {};
	props.loop = loop;
	props.reversed = reversed;
	cjs.MovieClip.apply(this,[props]);

	// timeline functions:
	this.frame_0 = function() {
		var self = this;
		this.stop();
		
		// 1. DAFTAR ALAT & BAHAN (Sesuai urutan visual checklist di gambar)
		var alatBenarArr2 = [
		    this.gula,      // Untuk checklist "Gula"
		    this.tabung2,   // Untuk checklist "tabung2"
		    this.tabung1,   // Untuk checklist "tabung1"
		    this.spiritus2, // Untuk checklist "spiritus2"
		    this.spiritus1  // Untuk checklist "spiritus1"
		];
		
		var alatSalahArr2 = [
		    this.pemanas_lama, 
		    this.stand_kecil2, 
		    this.tabungkecil2, 
		    this.garam2, 
		    this.penutup2
		]; 
		
		var semuaAlat2 = alatBenarArr2.concat(alatSalahArr2);
		var alatDiMeja2 = [];
		var checkArr2 = [];
		
		// 2. SETUP CHECKLIST (Centang hijau check1 - check5)
		for (var i = 1; i <= 5; i++) {
		    var chk = this["check" + i]; 
		    if (chk) {
		        checkArr2.push(chk);
		        chk.visible = false; 
		    }
		}
		
		// Sembunyikan tombol next di awal
		this.btnNext2.visible = false;
		
		// 3. FUNGSI DRAG & DROP
		semuaAlat2.forEach(function(alat) {
		    if (!alat) return;
		
		    alat.startX = alat.x;
		    alat.startY = alat.y;
		    alat.cursor = "pointer";
		
		    alat.on("mousedown", function(evt) {
		        self.addChild(alat); 
		        var p = self.globalToLocal(evt.stageX, evt.stageY);
		        alat.offset = { x: alat.x - p.x, y: alat.y - p.y };
		    });
		
		    alat.on("pressmove", function(evt) {
		        var p = self.globalToLocal(evt.stageX, evt.stageY);
		        alat.x = p.x + alat.offset.x;
		        alat.y = p.y + alat.offset.y;
		    });
		
		    alat.on("pressup", function(evt) {
		        var meja = self.meja2_mc; 
		        var localPos = meja.globalToLocal(evt.stageX, evt.stageY);
		
		        if (meja.hitTest(localPos.x, localPos.y)) {
		            var index = alatBenarArr2.indexOf(alat);
		
		            if (index !== -1) {
		                if (alatDiMeja2.indexOf(alat) === -1) {
		                    alatDiMeja2.push(alat);
		                }
		                
		                alat.mouseEnabled = false;
		                alat.cursor = "default";
		                createjs.Tween.get(alat).to({ scale: 1.1 }, 100).to({ scale: 1 }, 100);
		
		                updateChecklist();
		                cekKelengkapanMeja2();
		            } else {
		                balikKeRak2(alat);
		            }
		        } else {
		            balikKeRak2(alat);
		        }
		    });
		});
		
		// 4. FUNGSI UPDATE CHECKLIST
		function updateChecklist() {
		    if (alatDiMeja2.indexOf(self.gula) !== -1) { if (checkArr2[0]) checkArr2[0].visible = true; }
		    if (alatDiMeja2.indexOf(self.tabung2) !== -1) { if (checkArr2[1]) checkArr2[1].visible = true; }
		    if (alatDiMeja2.indexOf(self.tabung1) !== -1) { if (checkArr2[2]) checkArr2[2].visible = true; }
		    if (alatDiMeja2.indexOf(self.spiritus2) !== -1) { if (checkArr2[3]) checkArr2[3].visible = true; }
		    if (alatDiMeja2.indexOf(self.spiritus1) !== -1) { if (checkArr2[4]) checkArr2[4].visible = true; }
		}
		
		function balikKeRak2(obj) {
		    createjs.Tween.get(obj, { override: true })
		        .to({ x: obj.startX, y: obj.startY }, 500, createjs.Ease.backOut);
		}
		
		function cekKelengkapanMeja2() {
		    // Munculkan tombol Next jika ke-5 alat sudah di meja
		    if (alatDiMeja2.length >= 5) {
		        self.btnNext2.visible = true;
		    }
		}
		
		// 5. NAVIGASI (NEXT & BACK SESUAI REQUEST)
		if(this.btnNext2) {
		    this.btnNext2.on("click", function() {
		        // Bersihkan objek sebelum pindah frame
		        semuaAlat2.forEach(function(a) { if(a) a.visible = false; });
		        checkArr2.forEach(function(c) { if(c) c.visible = false; });
		        
		        // Pindah ke frame berikutnya (Frame 2 dalam urutan timeline)
		        self.gotoAndStop(self.currentFrame + 1); 
		    });
		}
		
		// Tombol Kembali ke Menu Utama
		this.btn_back_praktikum2.cursor = "pointer";
		this.btn_back_praktikum2.on("click", function() {
		    exportRoot.gotoAndStop("menu_utama");
		}.bind(this));
		
		// Tombol Kembali ke Pilihan Praktikum
		this.btn_back_pilihan2.cursor = "pointer";
		this.btn_back_pilihan2.on("click", function() {
		    exportRoot.gotoAndStop("pilih_praktikum");
		}.bind(this));
	}
	this.frame_1 = function() {
		this.stop();
		
		var _this = this;
		
		_this.btnNext.on('click', function() {
			var nextFrame = _this.currentFrame + 1;
			_this.gotoAndPlay(nextFrame);
			
		});
	}
