		// Menggunakan playVO agar backsound tetap menyala di latar belakang
		if (typeof playVO === "function") {
		    playVO("materiID"); 
		} else {
		    // Jika fungsi playVO belum terbaca, kita hentikan VO sebelumnya saja
		    if (exportRoot.currentVO) { exportRoot.currentVO.stop(); }
		    exportRoot.currentVO = createjs.Sound.play("materiID", {volume: 0.6});
		}
		
		// --- 2. KONFIGURASI TOMBOL MATERI (BACKSOUND TETAP NYALA) ---
		
		// Materi 1 (Uap)
		this.materi1.cursor = "pointer";
		this.materi1.removeAllEventListeners("click");
		this.materi1.on("click", function() {
		    if (exportRoot.currentVO) { exportRoot.currentVO.stop(); } // Hanya stop VO
		    this.gotoAndStop("uap"); 
		}.bind(this));
		
		// Materi 2 (Didih)
		this.materi3.cursor = "pointer";
		this.materi3.removeAllEventListeners("click");
